/**
 * @file    gui_ui.h
 * @brief   Phone UI: screen state machine, buttons, status bar, home launcher,
 *          dialer keypad, and placeholder sub-screens (SMS / contacts / settings).
 *
 * No framebuffer: every change redraws only what it touches (a full screen
 * redraw is still just a few ms on the 8080-parallel ILI9341).
 *
 * Chinese text comes from gui_strings.c (GB2312 byte literals, generated by
 * tools/gen_ui_strings.py). This file is pure ASCII on purpose.
 */
#ifndef __GUI_UI_H
#define __GUI_UI_H

#include "stm32f1xx.h"

void UI_Init(void);      /* draw the home screen */
void UI_Poll(void);      /* read touch, dispatch to the current screen */
void UI_Tick(void);      /* 1-Hz-ish clock refresh + transient timeouts */
void UI_Calibrate(void); /* interactive 3-point touch calibration (first boot) */

#endif /* __GUI_UI_H */
